INSERT INTO planner_progress_note(id,task_id,day,note,author_id) VALUES ('b0588383-9e42-59f0-936a-82d948b25394','9ca61a25-cea7-455e-85a3-321040019fae','2025-08-29','Во ред, разбирам. Продолжуваме со креирање на следниот документ во серијата за Фазата на Размножување, конкретно **GACP-IRR-001-APP-02**. Овој додаток ги содржи шаблоните за евиденција кои се неопходни за одржување на следливост и усогласеност со GACP/GMP стандардите. Обрасците се дизајнирани да бидат јасни, сеопфатни и лесни за пополнување од страна на персоналот, со целосен двојазичен формат. --- **ДОДАТОК НА СТАНДАРДНА ОПЕРАТИВНА ПОСТАПКА** ╏ **STANDARD OPERATING PROCEDURE APPENDIX** **Наслов:** Фаза на размножување - Обрасци за евиденција ╏ **Title:** Propagation Phase - Log Sheet Template','b1b1b1b1-0000-4000-8000-0000000000a1');
