INSERT INTO planner_task(id,parent_id,department_id,owner_id,created_by,title,description,status,priority,week_start,days,tags,node_kind,is_sop,annex_count,created_at,started_at,ended_at,updated_at,completed_at) VALUES ('aa2f41c7-6585-4b93-9664-786d694150a7',NULL,'638d6222-ec62-5a56-a065-da0d72455e30','b1b1b1b1-0000-4000-8000-0000000000a1','b1b1b1b1-0000-4000-8000-0000000000a1','Draft batch micro-sampling plan PP-QC-SP-001/26','Bilingual MK|EN sampling plan and execution protocol for representative sampling (600 g bRS) of 21 production batches held in secure storage, primarily for microbiological purity before sale. Includes per-batch N/n/target table (WHO TRS 929 Annex 4 r-plan, n=ceil(1.5*sqrt(N))), aseptic Grade D handling, pooling and split (micro 40 g, rRS 200 g, sRS 200 g, mRS 160 g) and ALCOA+ records. Remaining: confirm rRS/sRS/mRS contractual mapping, assign final document code (currently placeholder PP-QC-SP-001/26), add shelf-life/stability justification for the aged stock, and obtain QA approval and signatures.','working','high','2026-06-22',ARRAY['2026-06-24','2026-06-27']::text[],ARRAY['source:claude.ai','capture-v6','sampling-plan','microbiology','PP-QC-SP-001/26','bilingual','secure-warehouse']::text[],'task',false,0,'2026-06-28T02:37:13.767566+00:00','2026-06-28T02:37:13.767566+00:00',(GREATEST(('2026-06-28T06:46:22.699263+00:00')::timestamptz, ('2026-06-28T02:37:13.767566+00:00')::timestamptz) + interval '1 hour'),'2026-06-28T02:37:13.767566+00:00',NULL) ON CONFLICT (id) DO NOTHING;
