INSERT INTO planner_task(id,parent_id,department_id,owner_id,created_by,title,description,status,priority,week_start,days,tags,node_kind,is_sop,annex_count,created_at,started_at,ended_at,updated_at,completed_at) VALUES ('89847802-59a5-4cf0-90a1-6fbe3ac1658d',NULL,'638d6222-ec62-5a56-a065-da0d72455e30','b1b1b1b1-0000-4000-8000-0000000000a1','b1b1b1b1-0000-4000-8000-0000000000a1','Determine Ph. Eur. sampling & micro reference for Cannabis flos','Regulatory determination that Ph. Eur. 2.8.20 (Herbal drugs: Sampling and sample preparation) governs container selection and chemical sample preparation for dried cannabis flower via monograph Cannabis flos 3028 with Herbal drugs 1433, but is unsuitable for microbiological sampling because its milling/quartering/sieving destroys micro integrity. Concluded that micro is sampled aseptically in Grade D and tested per Ph. Eur. 2.6.12/2.6.13 with route-based limits (5.1.8/5.1.4), and recommended the WHO TRS 929 Annex 4 r-plan n=ceil(1.5*sqrt(N)) on quality-risk grounds (ICH Q9). Remaining: keep the conclusions reflected in the controlled sampling plan and monitor the no-harmonised-inhalation-limit position.','done','high','2026-06-22',ARRAY['2026-06-24']::text[],ARRAY['source:claude.ai','capture-v6','microbiology','sampling','regulatory-analysis','ph-eur','Ph.Eur-2.8.20','WHO-TRS-929','ICH-Q9']::text[],'task',false,0,'2026-06-28T02:37:13.767566+00:00','2026-06-28T02:37:13.767566+00:00',(GREATEST(('2026-06-24')::timestamptz, ('2026-06-28T02:37:13.767566+00:00')::timestamptz) + interval '1 hour'),'2026-06-28T02:37:13.767566+00:00','2026-06-28T02:37:13.767566+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO planner_progress_note(id,task_id,day,note,author_id) VALUES ('69703521-37c8-505b-af3c-98e267afec2e','89847802-59a5-4cf0-90a1-6fbe3ac1658d',NULL,'{"date": "2026-06-24", "progress": "Resolved the 2.8.20 vs microbiology applicability question; set micro testing route 2.6.12/2.6.13 with 5.1.8/5.1.4 limits, the n=ceil(1.5*sqrt(N)) r-plan basis, and clarified Annex 19 / ICH Q7 retention sizing.", "est_minutes": 90}','b1b1b1b1-0000-4000-8000-0000000000a1');
